#!/usr/bin/env python3
"""Score the FULLPF cell against the pre-registration in PREREG-FULLPF.md.

Primary outcome: greps/session (low variance -> real power at n=30).
Dose-response: grep reduction vs body-line count in the injected payload.
Secondary: pre-edit / total output tokens, total tokens, all with bootstrap CIs.
Integrity: ENOSPC, timeouts, censored, FOREIGN_CACHE_TOUCHED, CORRUPT_CC_OUT, empty patches.

Usage: python3 tools/score_fullpf.py [TAG]     (default TAG=FULLPF)
"""
import json, os, glob, math, re, statistics, random, sys, collections

SUITE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(SUITE)
random.seed(17)
TAG = sys.argv[1] if len(sys.argv) > 1 else "FULLPF"
PRIOR = ("RUNG2J", "RUNG2K", "RUNG2M", "FIXSTACK", "RUNG2I")

f = lambda x: (f"saving {-x:.1f}%" if x < 0 else f"COSTING {x:.1f}%")


def sess_path(cc):
    try:
        sid = json.load(open(cc)).get("session_id")
    except Exception:
        return None
    g = glob.glob(os.path.expanduser(f"~/.claude/projects/*/{sid}.jsonl"))
    return g[0] if g else None


def session_stats(path):
    """One record per message.id, UNION of content blocks (the transcript splits a single
    API response across several lines that share an id and output_tokens)."""
    blocks, out, order = collections.defaultdict(list), {}, []
    for line in open(path, errors="replace"):
        try:
            d = json.loads(line)
        except Exception:
            continue
        if d.get("type") != "assistant":
            continue
        m = d.get("message") or {}
        mid = m.get("id")
        if not mid:
            continue
        if mid not in blocks:
            order.append(mid)
        for b in m.get("content") or []:
            if isinstance(b, dict):
                blocks[mid].append(b)
        out[mid] = max(out.get(mid, 0), (m.get("usage") or {}).get("output_tokens") or 0)
    greps = gq = pre = 0
    opre = 0
    edited = False
    for mid in order:
        tools = [(b.get("name"), b.get("input") or {}) for b in blocks[mid] if b.get("type") == "tool_use"]
        if not edited:
            pre += 1
            opre += out.get(mid, 0)
        for n, inp in tools:
            c = (inp.get("command") or "")[:400] if n == "Bash" else ""
            if n in ("Grep", "Glob") or re.search(r"\b(grep|rg|ag)\b", c):
                greps += 1
            if re.search(r"eg-q|graph-query|entire graph", c):
                gq += 1
        if any(n in ("Edit", "Write", "MultiEdit", "NotebookEdit") for n, _ in tools):
            edited = True
    return dict(greps=greps, gq=gq, pre=pre, out_pre=opre, out=sum(out.values()), turns=len(order))


def total_tokens(cc):
    j = json.load(open(cc))
    u = j.get("usage") or {}
    v = sum(u.get(k, 0) for k in ("cache_read_input_tokens", "cache_creation_input_tokens",
                                  "input_tokens", "output_tokens"))
    if not v:
        for m in (j.get("modelUsage") or {}).values():
            v += sum(m.get(k, 0) for k in ("cacheReadInputTokens", "cacheCreationInputTokens",
                                           "inputTokens", "outputTokens"))
    return v, (j.get("total_cost_usd") or 0), j.get("subtype")


def body_lines(d):
    p = f"{d}/prefetch.payload"
    if not os.path.exists(p):
        return None
    txt = open(p, errors="ignore").read()
    return sum(1 for ln in txt.splitlines() if ln.startswith("  ") and ln.strip()
               and not ln.strip()[0].isdigit())


def collect(pattern, arm):
    rows = {}
    for d in sorted(glob.glob(pattern)):
        iid = os.path.basename(d)
        cc = f"{d}/cc_out.json"
        if not (os.path.exists(cc) and os.path.getsize(cc)):
            continue
        s = sess_path(cc)
        if not s:
            continue
        try:
            tok, usd, sub = total_tokens(cc)
        except Exception:
            continue
        st = session_stats(s)
        st.update(iid=iid, dir=d, tok=tok, usd=usd, subtype=sub, arm=arm,
                  bodies=body_lines(d),
                  patch=os.path.getsize(f"{d}/patch.diff") if os.path.exists(f"{d}/patch.diff") else 0)
        rows[iid] = st
    return rows


def integrity(rows, label):
    bad = collections.Counter()
    for iid, r in rows.items():
        for marker, why in (("FOREIGN_CACHE_TOUCHED", "foreign_cache"), ("CORRUPT_CC_OUT", "corrupt_cc_out")):
            if os.path.isfile(os.path.join(r["dir"], marker)):
                bad[why] += 1
        if r["usd"] <= 0:
            bad["zero_cost"] += 1
        if r["patch"] == 0:
            bad["empty_patch"] += 1
        if r["subtype"] and r["subtype"] != "success":
            bad[f"subtype:{r['subtype']}"] += 1
        for lg in glob.glob(os.path.join(r["dir"], "*.log")):
            try:
                t = open(lg, errors="ignore").read()
            except Exception:
                continue
            if "No space left" in t or "ENOSPC" in t:
                bad["enospc"] += 1
                break
    print(f"  {label:24s} n={len(rows):3d}  issues: {dict(bad) if bad else 'none'}")
    return bad


def boot_ratio(new, ref, key, B=20000):
    """unpaired ratio-of-means bootstrap (new arm vs a pooled reference arm)"""
    a = [r[key] for r in new]
    b = [r[key] for r in ref]
    if not a or not b:
        return None
    pt = (statistics.mean(a) / statistics.mean(b) - 1) * 100
    xs = []
    for _ in range(B):
        ma = statistics.mean(random.choice(a) for _ in a)
        mb = statistics.mean(random.choice(b) for _ in b)
        xs.append((ma / mb - 1) * 100)
    xs.sort()
    return pt, xs[int(.975 * B)], xs[int(.025 * B)]


new = collect(f"results/{TAG}_r1_eg/eg/*", "fullpf")
if not new:
    sys.exit(f"no sessions found under results/{TAG}_r1_eg/eg/ — has the cell run?")
minimal, base = {}, {}
for t in PRIOR:
    for iid, r in collect(f"results/{t}_r1_eg/eg/*", "minimal").items():
        minimal[f"{t}:{iid}"] = r
    for iid, r in collect(f"results/{t}_r1_baseline/baseline/*", "baseline").items():
        base[f"{t}:{iid}"] = r

print(f"=== FULLPF ({TAG}) vs pooled prior arms ===\n")
print("INTEGRITY")
integrity(new, f"{TAG} eg (full payload)")
integrity(minimal, "prior eg (minimal)")
integrity(base, "prior baseline")

N, M, B_ = list(new.values()), list(minimal.values()), list(base.values())
print("\nPRIMARY — greps/session")
for lbl, ref in (("vs prior eg (minimal)", M), ("vs baseline", B_)):
    r = boot_ratio(N, ref, "greps")
    if r:
        print(f"  {lbl:24s} {statistics.mean(x['greps'] for x in ref):5.2f} -> "
              f"{statistics.mean(x['greps'] for x in N):5.2f}   {f(r[0]):>16s}  CI [{f(r[1])}, {f(r[2])}]")
g_new = statistics.mean(x["greps"] for x in N)
print(f"\n  PRE-REGISTERED BAR: greps/session < 10.0  ->  measured {g_new:.2f}  "
      f"{'MET' if g_new < 10.0 else 'NOT MET'}")
print(f"  FALSIFICATION BAR : greps/session >= 13.0 ->  "
      f"{'HYPOTHESIS FALSIFIED' if g_new >= 13.0 else 'not falsified'}")

print("\nSECONDARY (unpaired vs pooled refs; quote the interval)")
for key, lbl in (("out_pre", "OUTPUT pre-edit"), ("out", "OUTPUT total"),
                 ("tok", "TOTAL tokens"), ("pre", "pre-edit turns"),
                 ("turns", "assistant turns"), ("gq", "graph calls")):
    r = boot_ratio(N, B_, key)
    if r:
        print(f"  {lbl:18s} base {statistics.mean(x[key] for x in B_):9.1f} -> "
              f"{statistics.mean(x[key] for x in N):9.1f}  {f(r[0]):>16s}  CI [{f(r[1])}, {f(r[2])}]")

print("\nDOSE-RESPONSE — grep reduction vs body lines in the payload")
doses = [(r["bodies"], r) for r in N if r["bodies"] is not None]
if len(doses) >= 9:
    doses.sort(key=lambda t: t[0])
    k = len(doses) // 3
    for lbl, sel in (("bottom third (few bodies)", doses[:k]),
                     ("middle third", doses[k:2 * k]),
                     ("top third (many bodies)", doses[2 * k:])):
        gs = statistics.mean(r["greps"] for _, r in sel)
        bd = statistics.mean(b for b, _ in sel)
        # per-instance comparison against the SAME instance under minimal, where available
        pair = []
        for _, r in sel:
            m = [v["greps"] for kk, v in minimal.items() if kk.endswith(":" + r["iid"])]
            if m:
                pair.append(math.log(max(r["greps"], 1) / max(statistics.mean(m), 1)))
        delta = (math.exp(sum(pair) / len(pair)) - 1) * 100 if pair else float("nan")
        print(f"  {lbl:26s} n={len(sel):2d}  body lines {bd:6.1f}  greps {gs:5.2f}  "
              f"vs same-instance minimal: {f(delta) if pair else 'n/a'}")
else:
    print("  too few instances with payloads to tercile")

print("\nPER-INSTANCE (greps: minimal -> fullpf)")
for r in sorted(N, key=lambda r: r["iid"]):
    m = [v["greps"] for kk, v in minimal.items() if kk.endswith(":" + r["iid"])]
    mm = f"{statistics.mean(m):5.2f}" if m else "  n/a"
    print(f"  {r['iid']:34s} bodies {str(r['bodies']):>4s}  {mm} -> {r['greps']:5.2f}   "
          f"turns {r['turns']:3d}  out {r['out']:7d}  {'GATE-FAIL' if (r['usd'] <= 0 or r['patch'] == 0) else ''}")

