#!/usr/bin/env python3
"""Phase decomposition of Opus sessions — LOCATE / ITERATE / POST.

P0.1 of the GOAL25 plan. Every per-phase gate depends on this, and nothing like it existed:
`grep -l "LOCATE\\|ITERATE"` over tools/, scripts/ and bench/ returned nothing, so the published
phase anatomy has only ever been produced as a one-off.

Definitions (an "op" is one assistant API call = one distinct message.id):
  LOCATE   calls before the FIRST edit to a checkout file
  ITERATE  first edit .. last edit inclusive
  POST     calls after the LAST edit

Within ITERATE each shell-explore op is tagged failure-tied when a nonzero-exit Bash appears in the
preceding 2 calls; the residual (not failure-tied) pool is the multi-site enumeration the plan's G2
gate targets.

TRANSCRIPT PARSING — the trap that has produced two wrong findings this campaign:
one assistant API response is written as SEVERAL JSONL lines that SHARE a message.id, one content
block each. Keeping "the longest" line keeps the `thinking` block and DROPS the `tool_use`. Blocks
must be UNIONed per message.id. output_tokens is repeated on each line, so take max, never sum.

Validation target (published anatomy, n=445): LOCATE 18.92/20.17, ITERATE 17.60/21.28, POST 9.51/8.95
`python3 tools/phases.py --validate` prints the comparison; anything beyond 0.3 calls means the
numbers this plan is sized against are themselves wrong.

Usage:
  tools/phases.py --cells FULLPF_r1_eg,FULLPF_r1_baseline   per-cell anatomy
  tools/phases.py --validate                                 reproduce the published anatomy
  tools/phases.py --json out.json                            machine-readable, for the gate checks
"""
import argparse
import collections
import glob
import json
import os
import re
import statistics
import sys

SUITE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
EDIT_TOOLS = ("Edit", "Write", "MultiEdit", "NotebookEdit")
# first-stage locate commands only; a grep AFTER a pipe is an output filter, not a locate op
LOCATE_RX = re.compile(r"\b(grep|rg|egrep|fgrep|ag|ack|find|fd)\b")
READ_RX = re.compile(r"\b(cat|head|tail|sed|awk|less|more)\b")


def transcript_for(cc_out):
    try:
        sid = json.load(open(cc_out)).get("session_id")
    except Exception:
        return None
    if not sid:
        return None
    hits = glob.glob(os.path.expanduser(f"~/.claude/projects/*/{sid}.jsonl"))
    return hits[0] if hits else None


def turns(path):
    """One record per message.id with the UNION of its content blocks."""
    blocks = collections.defaultdict(list)
    out = {}
    order = []
    for line in open(path, errors="replace"):
        try:
            d = json.loads(line)
        except Exception:
            continue
        if d.get("type") != "assistant":
            continue
        m = d.get("message") or {}
        mid = m.get("id")
        if not mid:
            continue
        if mid not in blocks:
            order.append(mid)
        for b in m.get("content") or []:
            if isinstance(b, dict):
                blocks[mid].append(b)
        out[mid] = max(out.get(mid, 0), (m.get("usage") or {}).get("output_tokens") or 0)
    recs = []
    for mid in order:
        bs = blocks[mid]
        tools = [(b.get("name"), b.get("input") or {}, b.get("id")) for b in bs if b.get("type") == "tool_use"]
        recs.append(dict(id=mid, tools=tools, out=out.get(mid, 0)))
    return recs


def tool_errors(path):
    """tool_use_id -> is_error, so a failed Bash can be located in the preceding calls."""
    errs = {}
    for line in open(path, errors="replace"):
        try:
            d = json.loads(line)
        except Exception:
            continue
        if d.get("type") != "user":
            continue
        c = (d.get("message") or {}).get("content")
        for b in c if isinstance(c, list) else []:
            if isinstance(b, dict) and b.get("type") == "tool_result":
                errs[b.get("tool_use_id")] = bool(b.get("is_error"))
    return errs


def first_stage(cmd):
    """Text before the first pipe — a grep after `|` filters output, it does not locate."""
    return cmd.split("|")[0] if "|" in cmd else cmd


def classify(recs, errs):
    edit_ix = [k for k, r in enumerate(recs) if any(n in EDIT_TOOLS for n, _, _ in r["tools"])]
    if edit_ix:
        first_edit, last_edit = edit_ix[0], edit_ix[-1]
    else:
        first_edit = last_edit = len(recs)  # never edited -> everything is LOCATE
    res = dict(turns=len(recs), locate=0, iterate=0, post=0,
               locate_ops=0, iterate_explore=0, iterate_explore_failtied=0,
               post_ops=0, edits=len(edit_ix), graph_calls=0)
    for k, r in enumerate(recs):
        phase = "locate" if k < first_edit else ("post" if k > last_edit else "iterate")
        res[phase] += 1
        explore = False
        for name, inp, _tid in r["tools"]:
            if name == "Bash":
                c = first_stage((inp.get("command") or "")[:600])
                if re.search(r"eg-q|entire graph|graph-query", c):
                    res["graph_calls"] += 1
                    continue
                if LOCATE_RX.search(c) or READ_RX.search(c):
                    explore = True
            elif name in ("Grep", "Glob", "Read"):
                explore = True
        if not explore:
            continue
        if phase == "locate":
            res["locate_ops"] += 1
        elif phase == "post":
            res["post_ops"] += 1
        else:
            res["iterate_explore"] += 1
            # failure-tied: a nonzero-exit Bash in the preceding 2 calls
            tied = False
            for j in range(max(0, k - 2), k):
                for _n, _i, tid in recs[j]["tools"]:
                    if tid and errs.get(tid):
                        tied = True
            if tied:
                res["iterate_explore_failtied"] += 1
    return res


def scan(pattern):
    rows = []
    for cc in sorted(glob.glob(pattern)):
        if not os.path.getsize(cc):
            continue
        t = transcript_for(cc)
        if not t:
            continue
        try:
            recs = turns(t)
            if not recs:
                continue
            r = classify(recs, tool_errors(t))
        except Exception:
            continue
        r["instance"] = os.path.basename(os.path.dirname(cc))
        rows.append(r)
    return rows


def summarize(rows, label):
    if not rows:
        return None
    m = lambda k: statistics.mean(r[k] for r in rows)
    print(f"  {label:28s} n={len(rows):3d}  turns {m('turns'):5.2f} | "
          f"LOCATE {m('locate'):5.2f} | ITERATE {m('iterate'):5.2f} | POST {m('post'):5.2f} | "
          f"loc-ops {m('locate_ops'):5.2f} | in-loop {m('iterate_explore'):4.2f} "
          f"(fail-tied {m('iterate_explore_failtied'):4.2f}, residual "
          f"{m('iterate_explore') - m('iterate_explore_failtied'):4.2f}) | "
          f"post-ops {m('post_ops'):4.2f} | graph {m('graph_calls'):4.2f}")
    return {k: m(k) for k in ("turns", "locate", "iterate", "post", "locate_ops",
                              "iterate_explore", "iterate_explore_failtied", "post_ops", "graph_calls")}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--cells", default="")
    ap.add_argument("--validate", action="store_true")
    ap.add_argument("--json", default="")
    a = ap.parse_args()
    os.chdir(SUITE)
    out = {}

    if a.validate:
        # pool every eg arm and every baseline arm across all cells, as the published anatomy did
        eg = scan("results/*_r1_eg/eg/*/cc_out.json")
        base = scan("results/*_r1_baseline/baseline/*/cc_out.json")
        print("POOLED ANATOMY (all cells)")
        e = summarize(eg, "eg (all cells)")
        b = summarize(base, "baseline (all cells)")
        print("\nVALIDATION vs published anatomy (n=445): tolerance 0.30 calls")
        ok = True
        for name, got, want in (("LOCATE eg", e["locate"], 18.92), ("LOCATE base", b["locate"], 20.17),
                                ("ITERATE eg", e["iterate"], 17.60), ("ITERATE base", b["iterate"], 21.28),
                                ("POST eg", e["post"], 9.51), ("POST base", b["post"], 8.95)):
            d = abs(got - want)
            flag = "OK " if d <= 0.30 else "OFF"
            if d > 0.30:
                ok = False
            print(f"  {flag} {name:14s} got {got:6.2f}  want {want:6.2f}  delta {d:5.2f}")
        print(f"\n  => {'REPRODUCES' if ok else 'DOES NOT REPRODUCE'} the published anatomy")
        out = dict(eg=e, baseline=b, reproduces=ok)
    else:
        cells = [c for c in a.cells.split(",") if c]
        print("PER-CELL ANATOMY")
        for c in cells:
            arm = "baseline" if c.endswith("_baseline") else "eg"
            out[c] = summarize(scan(f"results/{c}/{arm}/*/cc_out.json"), c)

    if a.json:
        json.dump(out, open(a.json, "w"), indent=1)
        print(f"\nwrote {a.json}")


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""P0.4 — the riskiest assumption in the GOAL25 plan, falsified for $0.

Every graph number measured to date used a HARNESS-authored query. On 5 of 30 instances that query
literally leads with the gold file path, extracted from the issue's GitHub permalink by O35_QUERY_V3.
The tool's own doctrine says the AGENT authors the query, in one sentence, from the issue.

So: can an agent-plausible query find the gold file without the leak?

Query forms tested per instance (all path-free, URLs stripped):
  title   - the issue's first line, which is what a one-sentence query looks like
  first2  - title + first two sentences of the body
  base1   - the baseline arm's OWN first grep string on that instance (what a no-tool agent actually
            reached for), recovered from its transcript

GATE: gold-file recall >= 50% @ top-5 on the best agent-plausible form.
Below that, the documented workflow does not survive SWE-bench issue text, and the whole route dies
before a dollar is spent.

Usage: tools/recall_agent_query.py [--limit N] [--json out.json]
"""
import argparse
import glob
import json
import math
import os
import re
import subprocess
import sys

SUITE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
EG = os.environ.get("ENTIRE_GRAPH",
                    "/private/tmp/claude-501/-Users-suhaan-devenv/"
                    "73009f6a-a642-4aaa-8da3-51eb6bcc5b49/scratchpad/eg-94009ef")
WTROOT = "/tmp/recall_wt"
TOPK = 5


def gold_files(patch):
    return sorted(set(re.findall(r"\+\+\+ b/(\S+)", patch or "")))


def strip_paths(text):
    """Remove URLs and anything that looks like a file path — the agent writes prose, not paths."""
    t = re.sub(r"https?://\S+", " ", text or "")
    t = re.sub(r"[\w./-]+\.(?:java|py|go|rs|rb|php|js|ts|tsx|c|h|cc|cpp|hpp|mjs|cjs)\b", " ", t)
    t = re.sub(r"\s+", " ", t)
    return t.strip()


def queries_for(task, baseline_grep):
    ps = task.get("problem_statement", "") or ""
    body = strip_paths(ps)
    lines = [l.strip() for l in ps.strip().splitlines() if l.strip()]
    title = strip_paths(lines[0]) if lines else ""
    sents = re.split(r"(?<=[.!?])\s+", body)
    q = {}
    if title:
        q["title"] = title[:200]
    if sents:
        q["first2"] = " ".join(sents[:2])[:240]
    if baseline_grep:
        q["base1"] = strip_paths(baseline_grep)[:200]
    return {k: v for k, v in q.items() if v and len(v) > 8}


def baseline_first_grep(iid):
    """The first thing the no-tool arm actually grepped for — a real agent-authored locate string."""
    for tag in ("FULLPF_r1_baseline", "RUNG2J_r1_baseline", "RUNG2I_r1_baseline"):
        cc = f"{SUITE}/results/{tag}/baseline/{iid}/cc_out.json"
        if not (os.path.exists(cc) and os.path.getsize(cc)):
            continue
        try:
            sid = json.load(open(cc)).get("session_id")
        except Exception:
            continue
        hits = glob.glob(os.path.expanduser(f"~/.claude/projects/*/{sid}.jsonl"))
        if not hits:
            continue
        for line in open(hits[0], errors="replace"):
            try:
                d = json.loads(line)
            except Exception:
                continue
            if d.get("type") != "assistant":
                continue
            for b in (d.get("message") or {}).get("content") or []:
                if not (isinstance(b, dict) and b.get("type") == "tool_use"):
                    continue
                inp = b.get("input") or {}
                if b.get("name") in ("Grep", "Glob"):
                    p = inp.get("pattern") or inp.get("query")
                    if p:
                        return p
                if b.get("name") == "Bash":
                    c = inp.get("command") or ""
                    m = re.search(r"""\b(?:grep|rg)\b[^|]*?["']([^"']{6,})["']""", c)
                    if m:
                        return m.group(1)
    return ""


def ensure_wt(repo, commit, wt):
    cache = f"{SUITE}/repo-cache/" + repo.replace("/", "__")
    if not os.path.isdir(cache):
        cache = f"{SUITE}/repo-cache/" + repo.replace("/", "_")
    if not os.path.isdir(cache):
        return None
    if os.path.isdir(wt):
        return wt
    os.makedirs(os.path.dirname(wt), exist_ok=True)
    r = subprocess.run(["git", "-C", cache, "worktree", "add", "--force", "--detach", wt, commit],
                       capture_output=True, text=True, timeout=900)
    return wt if r.returncode == 0 else None


def run_query(wt, iid, q):
    env = dict(os.environ)
    cmd = [EG, "search", "--query", q, "--repo", wt, "--profile", "full", "--format", "text",
           "--top-k", str(TOPK), "--max-snippet-lines", "2", "--max-context-bytes", "3000",
           "--cache-dir", f"{SUITE}/.eg_cache/{iid}"]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=900, env=env)
    except subprocess.TimeoutExpired:
        return []
    paths = []
    for ln in (r.stdout or "").splitlines():
        m = re.match(r"^\s*(\d+)\.\s+(\S+?):", ln)
        if m:
            paths.append(m.group(2))
    return paths[:TOPK]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--json", default="")
    a = ap.parse_args()
    os.chdir(SUITE)
    tasks = json.load(open("tasks/rep30_tasks.json"))["instances"]
    if a.limit:
        tasks = tasks[:a.limit]
    if not os.access(EG, os.X_OK):
        sys.exit(f"binary not executable: {EG}")

    forms = ("title", "first2", "base1")
    hit = {f: 0 for f in forms}
    seen = {f: 0 for f in forms}
    rows = []
    for t in tasks:
        iid, repo, commit = t["instance_id"], t["repo"], t["base_commit"]
        gold = set(gold_files(t.get("patch", "")))
        if not gold:
            continue
        wt = ensure_wt(repo, commit, f"{WTROOT}/{iid}")
        if not wt:
            print(f"  {iid:32s} SKIP (no worktree)", flush=True)
            continue
        qs = queries_for(t, baseline_first_grep(iid))
        rec = {"instance": iid, "gold": sorted(gold)}
        for f in forms:
            if f not in qs:
                rec[f] = None
                continue
            top = run_query(wt, iid, qs[f])
            ok = any(g in top for g in gold)
            seen[f] += 1
            hit[f] += int(ok)
            rec[f] = {"query": qs[f][:90], "hit": ok, "top": top[:3]}
        rows.append(rec)
        marks = "".join(("Y" if (rec.get(f) or {}).get("hit") else ("-" if rec.get(f) else "?")) for f in forms)
        print(f"  {iid:32s} [{marks}]  {' | '.join(sorted(gold))[:60]}", flush=True)

    print("\nGOLD-FILE RECALL @ top-5, agent-authored queries (no paths, no permalinks)")
    best = 0.0
    for f in forms:
        if seen[f]:
            r = hit[f] / seen[f] * 100
            best = max(best, r)
            print(f"  {f:8s} {hit[f]:2d}/{seen[f]:2d} = {r:5.1f}%")
    print(f"\n  BEST agent-plausible form: {best:.1f}%   GATE >= 50%  ->  "
          f"{'PASS' if best >= 50 else 'FAIL — documented workflow does not survive issue text'}")
    if a.json:
        json.dump({"rows": rows, "hit": hit, "seen": seen, "best": best}, open(a.json, "w"), indent=1)


if __name__ == "__main__":
    main()

