    return g[0] if g else None
def profile(path):
    blocks=collections.defaultdict(list); order=[]; errs={}
    for line in open(path,errors='replace'):
        try: d=json.loads(line)
        except Exception: continue
        if d.get('type')=='assistant':
            m=d.get('message') or {}; mid=m.get('id')
            if not mid: continue
            if mid not in blocks: order.append(mid)
            for b in m.get('content') or []:
                if isinstance(b,dict): blocks[mid].append(b)
        elif d.get('type')=='user':
            c=(d.get('message') or {}).get('content')
            for b in c if isinstance(c,list) else []:
                if isinstance(b,dict) and b.get('type')=='tool_result':
                    errs[b.get('tool_use_id')]=(bool(b.get('is_error')), len(str(b.get('content') or '')))
    kinds=collections.Counter(); nerr=0; rbytes=0
    for mid in order:
        for b in blocks[mid]:
            if b.get('type')!='tool_use': continue
            n=b.get('name'); inp=b.get('input') or {}
            k=n
            if n=='Bash':
                c=(inp.get('command') or '')[:300]
                if re.search(r'\b(pytest|cargo|mvn|gradle|npm|yarn|go test|phpunit|rspec|make|tox|jest)\b',c): k='Bash:build/test'
                elif re.search(r'\b(grep|rg|find|fd|ls)\b',c): k='Bash:search'
                elif re.search(r'\b(cat|head|tail|sed|awk)\b',c): k='Bash:read'
                else: k='Bash:other'
            kinds[k]+=1
            e=errs.get(b.get('id'))
            if e:
                if e[0]: nerr+=1
                rbytes+=e[1]
    return len(order),kinds,nerr,rbytes
